package com.nivor.health;
import com.nivor.health.HealthDtos.*;import jakarta.validation.Valid;import java.time.LocalDate;import java.util.List;import org.springframework.http.*;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.security.core.userdetails.UserDetails;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/health/records")public class HealthRecordController{private final HealthRecordService service;public HealthRecordController(HealthRecordService s){service=s;}@GetMapping public List<RecordView> list(@AuthenticationPrincipal UserDetails u,@RequestParam(required=false)LocalDate from,@RequestParam(required=false)LocalDate to){return service.list(u.getUsername(),from,to);}@GetMapping("/{id}")public RecordView get(@AuthenticationPrincipal UserDetails u,@PathVariable long id){return service.get(u.getUsername(),id);}@PostMapping public ResponseEntity<RecordView> create(@AuthenticationPrincipal UserDetails u,@Valid@RequestBody RecordRequest r){return ResponseEntity.status(HttpStatus.CREATED).body(service.create(u.getUsername(),r));}@PutMapping("/{id}")public RecordView update(@AuthenticationPrincipal UserDetails u,@PathVariable long id,@Valid@RequestBody RecordRequest r){return service.update(u.getUsername(),id,r);}@DeleteMapping("/{id}")public ResponseEntity<Void> delete(@AuthenticationPrincipal UserDetails u,@PathVariable long id){service.delete(u.getUsername(),id);return ResponseEntity.noContent().build();}}
